namespace sv_8e5e9cc4a97c467ab7d7d29a9334e3a8.Client.Services;

public sealed record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public sealed record StatusUpdate(
    DateTimeOffset Timestamp,
    string Status,
    string Location);

namespace sv_8e5e9cc4a97c467ab7d7d29a9334e3a8.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;

namespace sv_8e5e9cc4a97c467ab7d7d29a9334e3a8.Client.Services;

/// <summary>
/// Client-side implementation used when running on WebAssembly.
/// Calls the server API endpoint over HTTP.
/// </summary>
public sealed class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

using sv_8e5e9cc4a97c467ab7d7d29a9334e3a8.Client.Services;

namespace sv_8e5e9cc4a97c467ab7d7d29a9334e3a8.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new ShipmentDetails(
            TrackingNumber: "TRK-1001",
            Status: "In Transit",
            Location: "Memphis, TN",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 11, 17, 0, 0, TimeSpan.Zero),
            Updates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 7, 5, 9, 0, 0, TimeSpan.Zero), "Picked Up", "Los Angeles, CA"),
                new StatusUpdate(new DateTimeOffset(2026, 7, 6, 14, 30, 0, TimeSpan.Zero), "In Transit", "Phoenix, AZ"),
                new StatusUpdate(new DateTimeOffset(2026, 7, 7, 22, 15, 0, TimeSpan.Zero), "In Transit", "Memphis, TN"),
            ]),

        ["TRK-2002"] = new ShipmentDetails(
            TrackingNumber: "TRK-2002",
            Status: "Delivered",
            Location: "New York, NY",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 7, 12, 0, 0, TimeSpan.Zero),
            Updates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 7, 3, 8, 0, 0, TimeSpan.Zero), "Picked Up", "Chicago, IL"),
                new StatusUpdate(new DateTimeOffset(2026, 7, 4, 11, 0, 0, TimeSpan.Zero), "In Transit", "Cleveland, OH"),
                new StatusUpdate(new DateTimeOffset(2026, 7, 5, 16, 45, 0, TimeSpan.Zero), "Out for Delivery", "New York, NY"),
                new StatusUpdate(new DateTimeOffset(2026, 7, 5, 18, 20, 0, TimeSpan.Zero), "Delivered", "New York, NY"),
            ]),

        ["TRK-3003"] = new ShipmentDetails(
            TrackingNumber: "TRK-3003",
            Status: "Processing",
            Location: "Seattle, WA",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 14, 15, 0, 0, TimeSpan.Zero),
            Updates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 7, 7, 10, 0, 0, TimeSpan.Zero), "Label Created", "Seattle, WA"),
            ]),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

